import numpy as np

def defects(x, v, u, h):
    x, v, u = (np.asarray(a, dtype=float) for a in (x, v, u))
    dx = x[1:] - x[:-1] - h / 2 * (v[1:] + v[:-1])
    dv = v[1:] - v[:-1] - h / 2 * (u[1:] + u[:-1])
    return np.stack([dx, dv], axis=1)

