import numpy as np

def speed_profile(v_lim, ds, a_max):
    """v_lim: speed limit at each of n points spaced ds apart along a path. Return the fastest
    speeds v (same length) with v[0] = v[-1] = 0, v <= v_lim everywhere, and
    |v[i+1]**2 - v[i]**2| <= 2 * a_max * ds between neighbours."""
    return np.array(v_lim, dtype=float)

