import numpy as np

def speed_profile(v_lim, ds, a_max):
    v = np.array(v_lim, dtype=float)
    v[0] = v[-1] = 0.0
    for i in range(len(v) - 1):
        v[i + 1] = min(v[i + 1], np.sqrt(v[i] ** 2 + 2 * a_max * ds))
    for i in range(len(v) - 1, 0, -1):
        v[i - 1] = min(v[i - 1], np.sqrt(v[i] ** 2 + 2 * a_max * ds))
    return v
